253	            } else {
254	                source_groups_notes
255	                    .entry(parent)
256	                    .or_default()
257	                    .push(name.clone());
258	                moved_note_names.push(name);
259	            }
260	        }
261	
262	        for (parent, names) in source_groups_folders {
263	            self.repository.update_order_remove(&parent, &names, true)?;
264	        }
265	
266	        for (parent, names) in source_groups_notes {
267	            self.repository
268	                .update_order_remove(&parent, &names, false)?;
269	        }
270	
271	        if !moved_folder_names.is_empty() {
272	            self.repository
273	                .update_order_append(&destination_path, &moved_folder_names, true)?;
274	        }
275	        if !moved_note_names.is_empty() {
276	            self.repository
