283	    pub(crate) fn delete_items(&self, items: Vec<String>) -> Result<(), String> {
284	        self.repository.ensured_root()?;
285	        let mut parent_folder_groups: HashMap<PathBuf, Vec<String>> = HashMap::new();
286	        let mut parent_note_groups: HashMap<PathBuf, Vec<String>> = HashMap::new();
287	
