301	            let parent = full_path
302	                .parent()
303	                .ok_or_else(|| "Missing parent folder.".to_string())?
304	                .to_path_buf();
305	            let meta = self.repository.metadata(&full_path)?;
306	            if meta.is_dir() {
307	                self.repository.remove_dir_all(&full_path)?;
308	                parent_folder_groups.entry(parent).or_default().push(name);
309	            } else {
310	                self.repository.remove_file(&full_path)?;
311	                parent_note_groups.entry(parent).or_default().push(name);
312	            }
313	        }
314	
315	        for (parent, names) in parent_folder_groups {
316	            self.repository.update_order_remove(&parent, &names, true)?;
317	        }
318	
319	        for (parent, names) in parent_note_groups {
320	            self.repository
321	                .update_order_remove(&parent, &names, false)?;
322	        }
323	
324	        Ok(())
325	    }
326	
327	    pub(crate) fn rename_item(&self, path: &str, new_name: &str) -> Result<String, String> {
328	        self.repository.ensured_root()?;
329	        let full_path = self.repository.resolve_path(path)?;
330	        if self.repository.is_system_folder_path(&full_path) {
331	            return Err(format!(
332	                "Cannot rename system folder: {}",
333	                full_path.to_string_lossy()
334	            ));
335	        }
336	        let parent = full_path
337	            .parent()
338	            .ok_or_else(|| "Missing parent folder.".to_string())?;
339	        let old_name = full_path
340	            .file_name()
341	            .and_then(|name| name.to_str())
342	            .ok_or_else(|| "Invalid item name.".to_string())?
343	            .to_string();
344	        let new_path = parent.join(new_name);
345	        self.repository.rename(&full_path, &new_path)?;
346	        let is_folder = new_path.is_dir();
347	        self.repository
348	            .update_order_rename(parent, &old_name, new_name, is_folder)?;
349	
350	        Ok(self.repository.strip_root(&new_path))
351	    }
352	
353	    pub(crate) fn set_order(&self, args: SetOrderArgs) -> Result<(), String> {
354	        self.repository.ensured_root()?;
355	        let parent_path = self.repository.resolve_path(&args.parent)?;
356	        if self.repository.is_feed_folder_path(&parent_path) {
357	            return Ok(());
358	        }
359	        let order = OrderFile {
360	            folder_order: args.folder_order,
361	            note_order: args.note_order,
362	        };
363	        self.repository.write_order_file(&parent_path, &order)
364	    }
365	}
