use std::{collections::HashMap, path::PathBuf};

use crate::{
    ports::notes::{NoteBodyCrypto, NoteClock, NoteHistory, NoteIdGenerator, NotesRepository},
    CreateNoteArgs, CreateNoteResult, FolderNode, NoteFrontMatter, NoteMeta, OrderFile,
    SetNoteTimestampArgs, SetOrderArgs, FEED_FOLDER,
};

pub(crate) struct NotesService<R, C, H, I, T> {
    repository: R,
    crypto: C,
    history: H,
    ids: I,
    clock: T,
}

impl<R, C, H, I, T> NotesService<R, C, H, I, T>
where
    R: NotesRepository,
    C: NoteBodyCrypto,
    H: NoteHistory,
    I: NoteIdGenerator,
    T: NoteClock,
{
    pub(crate) fn new(repository: R, crypto: C, history: H, ids: I, clock: T) -> Self {
        Self {
            repository,
            crypto,
            history,
            ids,
            clock,
        }
    }

    pub(crate) fn get_tree(&self) -> Result<FolderNode, String> {
        self.repository.ensured_root()?;
        self.repository.build_tree()
    }

    pub(crate) fn read_note(&self, path: &str) -> Result<String, String> {
        let full_path = self.repository.resolve_path(path)?;
        if !full_path.exists() || !full_path.is_file() {
            return Err("Note file does not exist.".to_string());
        }
        let raw = self.repository.read_to_string(&full_path)?;
        let (_, body) = crate::parse_note_front_matter(&raw);
        self.crypto.decrypt_note_body(&body)
    }

    pub(crate) fn create_note(&self, args: CreateNoteArgs) -> Result<CreateNoteResult, String> {
        self.repository.ensured_root()?;
        let folder_rel = args
            .folder_path
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or(FEED_FOLDER);
        let folder_full = self.repository.resolve_path(folder_rel)?;
        if self.repository.is_storage_folder_path(&folder_full) {
            return Err(
                "Notes cannot be created inside recordings or attachments storage.".to_string(),
            );
        }
        self.repository.create_dir_all(&folder_full)?;

        let timestamp = args
            .timestamp_ms
            .or_else(|| self.clock.now_ms())
            .unwrap_or(0);
        let content = args.content.unwrap_or_default();
        let note_id = self.ids.generate_note_id();
        let fallback = format!(
            "note-{}",
            self.ids.uuid_tail_without_timestamp_prefix(&note_id)
        );
        let file_name = self.repository.allocate_note_file_name(
            &folder_full,
            timestamp,
            &note_id,
            &content,
            &fallback,
            args.file_name_format,
        )?;
        let path = folder_full.join(&file_name);
        let mut meta = NoteFrontMatter::default();
        meta.id = Some(note_id);
        meta.created_ms = Some(timestamp);
        meta.updated_ms = Some(timestamp);
        self.repository.write_note(&path, &meta, &content)?;
        if !self.repository.is_feed_folder_path(&folder_full) {
            self.repository
                .update_order_append(&folder_full, &[file_name], false)?;
        }

        Ok(CreateNoteResult {
            path: self.repository.strip_root(&path),
        })
    }

    pub(crate) fn write_note(&self, path: &str, content: &str) -> Result<(), String> {
        let full_path = self.repository.resolve_path(path)?;
        if let Some(parent) = full_path.parent() {
            self.repository.create_dir_all(parent)?;
        }
        let mut meta = if full_path.exists() {
            let existing = self.repository.read_to_string(&full_path)?;
            let (parsed, _) = crate::parse_note_front_matter(&existing);
            parsed
        } else {
            NoteFrontMatter::default()
        };
        if meta.id.is_none() {
            meta.id = Some(self.ids.generate_note_id());
        }
        let now = self.clock.now_ms();
        if meta.created_ms.is_none() {
            meta.created_ms = now;
        }
        meta.updated_ms = now.or(meta.updated_ms);
        self.repository.write_note(&full_path, &meta, content)
    }

    pub(crate) fn set_note_timestamp(&self, args: SetNoteTimestampArgs) -> Result<(), String> {
        let full_path = self.repository.resolve_path(&args.path)?;
        if !full_path.exists() || !full_path.is_file() {
            return Err("Note file does not exist.".to_string());
        }
        let raw = self.repository.read_to_string(&full_path)?;
        let (mut meta, body) = crate::parse_note_front_matter(&raw);
        let body = self.crypto.decrypt_note_body(&body)?;
        if meta.id.is_none() {
            meta.id = Some(self.ids.generate_note_id());
        }
        if meta.created_ms.is_none() || meta.created_ms.unwrap_or(i64::MAX) > args.timestamp_ms {
            meta.created_ms = Some(args.timestamp_ms);
        }
        meta.updated_ms = Some(args.timestamp_ms);
        self.repository.write_note(&full_path, &meta, &body)
    }

    pub(crate) fn get_note_meta(&self, path: &str) -> Result<NoteMeta, String> {
        let full_path = self.repository.resolve_path(path)?;
        let (front_matter_meta, metadata) = if full_path.exists() {
            let raw = self.repository.read_to_string(&full_path)?;
            let (front_matter_meta, _) = crate::parse_note_front_matter(&raw);
            (front_matter_meta, self.repository.metadata(&full_path)?)
        } else {
            (
                NoteFrontMatter::default(),
                self.repository.metadata(&full_path)?,
            )
        };
        let note_rel = self.repository.strip_root(&full_path);
        let (history_created_ms, history_updated_ms) = self
            .history
            .note_timestamps(&note_rel)
            .unwrap_or((None, None));

        let created_ms = front_matter_meta
            .created_ms
            .or(history_created_ms)
            .or_else(|| {
                metadata
                    .created()
                    .ok()
                    .and_then(|time| self.clock.time_to_ms(time))
            });
        let updated_ms = front_matter_meta
            .updated_ms
            .or(history_updated_ms)
            .or_else(|| {
                metadata
                    .modified()
                    .ok()
                    .and_then(|time| self.clock.time_to_ms(time))
            });
        Ok(NoteMeta {
            created_ms,
            updated_ms,
            note_type: front_matter_meta.note_type.clone(),
            recording_audio_path: front_matter_meta.recording_audio_path.clone(),
            handwriting_attachment_path: front_matter_meta.handwriting_attachment_path.clone(),
            transcription_status: front_matter_meta.transcription_status.clone(),
            transcription_error: front_matter_meta.transcription_error.clone(),
            transcription_updated_ms: front_matter_meta.transcription_updated_ms,
            ocr_status: front_matter_meta.ocr_status.clone(),
            ocr_error: front_matter_meta.ocr_error.clone(),
            ocr_updated_ms: front_matter_meta.ocr_updated_ms,
        })
    }

    pub(crate) fn move_items(&self, items: Vec<String>, destination: String) -> Result<(), String> {
        self.repository.ensured_root()?;
        let destination_path = self.repository.resolve_path(&destination)?;
        if !destination_path.exists() {
            return Err(format!(
                "Destination folder does not exist: {}",
                destination_path.to_string_lossy()
            ));
        }

        let mut source_groups_folders: HashMap<PathBuf, Vec<String>> = HashMap::new();
        let mut source_groups_notes: HashMap<PathBuf, Vec<String>> = HashMap::new();
        let mut moved_folder_names = Vec::new();
        let mut moved_note_names = Vec::new();

        for item in items {
            let source = self.repository.resolve_path(&item)?;
            if self.repository.is_system_folder_path(&source) {
                return Err(format!(
                    "Cannot move system folder: {}",
                    source.to_string_lossy()
                ));
            }
            if !source.exists() {
                return Err(format!(
                    "Source does not exist: {}",
                    source.to_string_lossy()
                ));
            }
            let meta = self.repository.metadata(&source).map_err(|err| {
                format!(
                    "Failed to read metadata for {}: {}",
                    source.to_string_lossy(),
                    err
                )
            })?;
            let name = source
                .file_name()
                .and_then(|n| n.to_str())
                .ok_or_else(|| "Invalid item name.".to_string())?
                .to_string();
            let parent = source
                .parent()
                .ok_or_else(|| "Missing parent folder.".to_string())?
                .to_path_buf();

            let target = destination_path.join(&name);
            self.repository.rename(&source, &target).map_err(|err| {
                format!(
                    "Move failed {} -> {}: {}",
                    source.to_string_lossy(),
                    target.to_string_lossy(),
                    err
                )
            })?;
            if meta.is_dir() {
                source_groups_folders
                    .entry(parent)
                    .or_default()
                    .push(name.clone());
                moved_folder_names.push(name);
            } else {
                source_groups_notes
                    .entry(parent)
                    .or_default()
                    .push(name.clone());
                moved_note_names.push(name);
            }
        }

        for (parent, names) in source_groups_folders {
            self.repository.update_order_remove(&parent, &names, true)?;
        }

        for (parent, names) in source_groups_notes {
            self.repository
                .update_order_remove(&parent, &names, false)?;
        }

        if !moved_folder_names.is_empty() {
            self.repository
                .update_order_append(&destination_path, &moved_folder_names, true)?;
        }
        if !moved_note_names.is_empty() {
            self.repository
                .update_order_append(&destination_path, &moved_note_names, false)?;
        }

        Ok(())
    }

    pub(crate) fn delete_items(&self, items: Vec<String>) -> Result<(), String> {
        self.repository.ensured_root()?;
        let mut parent_folder_groups: HashMap<PathBuf, Vec<String>> = HashMap::new();
        let mut parent_note_groups: HashMap<PathBuf, Vec<String>> = HashMap::new();

        for item in items {
            let full_path = self.repository.resolve_path(&item)?;
            if self.repository.is_system_folder_path(&full_path) {
                return Err(format!(
                    "Cannot delete system folder: {}",
                    full_path.to_string_lossy()
                ));
            }
            let name = full_path
                .file_name()
                .and_then(|n| n.to_str())
                .ok_or_else(|| "Invalid item name.".to_string())?
                .to_string();
            let parent = full_path
                .parent()
                .ok_or_else(|| "Missing parent folder.".to_string())?
                .to_path_buf();
            let meta = self.repository.metadata(&full_path)?;
            if meta.is_dir() {
                self.repository.remove_dir_all(&full_path)?;
                parent_folder_groups.entry(parent).or_default().push(name);
            } else {
                self.repository.remove_file(&full_path)?;
                parent_note_groups.entry(parent).or_default().push(name);
            }
        }

        for (parent, names) in parent_folder_groups {
            self.repository.update_order_remove(&parent, &names, true)?;
        }

        for (parent, names) in parent_note_groups {
            self.repository
                .update_order_remove(&parent, &names, false)?;
        }

        Ok(())
    }

    pub(crate) fn rename_item(&self, path: &str, new_name: &str) -> Result<String, String> {
        self.repository.ensured_root()?;
        let full_path = self.repository.resolve_path(path)?;
        if self.repository.is_system_folder_path(&full_path) {
            return Err(format!(
                "Cannot rename system folder: {}",
                full_path.to_string_lossy()
            ));
        }
        let parent = full_path
            .parent()
            .ok_or_else(|| "Missing parent folder.".to_string())?;
        let old_name = full_path
            .file_name()
            .and_then(|name| name.to_str())
            .ok_or_else(|| "Invalid item name.".to_string())?
            .to_string();
        let new_path = parent.join(new_name);
        self.repository.rename(&full_path, &new_path)?;
        let is_folder = new_path.is_dir();
        self.repository
            .update_order_rename(parent, &old_name, new_name, is_folder)?;

        Ok(self.repository.strip_root(&new_path))
    }

    pub(crate) fn set_order(&self, args: SetOrderArgs) -> Result<(), String> {
        self.repository.ensured_root()?;
        let parent_path = self.repository.resolve_path(&args.parent)?;
        if self.repository.is_feed_folder_path(&parent_path) {
            return Ok(());
        }
        let order = OrderFile {
            folder_order: args.folder_order,
            note_order: args.note_order,
        };
        self.repository.write_order_file(&parent_path, &order)
    }
}

use std::{fs::Metadata, path::PathBuf};

pub use crate::domain::notes::{
    CreateNoteResult, FolderNode, NoteFileNameFormat, NoteFrontMatter, NoteMeta, OrderFile,
};

// ── Trait ──────────────────────────────────────────────────────────────────────

pub trait NoteService {
    fn get_tree(&self) -> Result<FolderNode, String>;
    fn read_note(&self, path: &str) -> Result<String, String>;
    fn create_note(
        &self,
        folder_path: Option<&str>,
        content: Option<&str>,
        timestamp_ms: Option<i64>,
        file_name_format: NoteFileNameFormat,
    ) -> Result<CreateNoteResult, String>;
    fn write_note(&self, path: &str, content: &str) -> Result<(), String>;
    fn set_note_timestamp(&self, path: &str, timestamp_ms: i64) -> Result<(), String>;
    fn get_note_meta(&self, path: &str) -> Result<NoteMeta, String>;
    fn move_items(&self, items: &[String], destination: &str) -> Result<(), String>;
    fn delete_items(&self, items: &[String]) -> Result<(), String>;
    fn rename_item(&self, path: &str, new_name: &str) -> Result<String, String>;
    fn set_order(
        &self,
        parent: &str,
        folder_order: Vec<String>,
        note_order: Vec<String>,
    ) -> Result<(), String>;
}

pub(crate) trait NotesRepository {
    fn ensured_root(&self) -> Result<PathBuf, String>;
    fn resolve_path(&self, rel: &str) -> Result<PathBuf, String>;
    fn strip_root(&self, path: &std::path::Path) -> String;
    fn build_tree(&self) -> Result<FolderNode, String>;
    fn read_to_string(&self, path: &std::path::Path) -> Result<String, String>;
    fn metadata(&self, path: &std::path::Path) -> Result<Metadata, String>;
    fn create_dir_all(&self, path: &std::path::Path) -> Result<(), String>;
    fn rename(&self, source: &std::path::Path, target: &std::path::Path) -> Result<(), String>;
    fn remove_dir_all(&self, path: &std::path::Path) -> Result<(), String>;
    fn remove_file(&self, path: &std::path::Path) -> Result<(), String>;
    fn write_note(
        &self,
        path: &std::path::Path,
        meta: &NoteFrontMatter,
        body: &str,
    ) -> Result<(), String>;
    fn allocate_note_file_name(
        &self,
        folder: &std::path::Path,
        timestamp_ms: i64,
        note_id: &str,
        content: &str,
        fallback_slug: &str,
        file_name_format: NoteFileNameFormat,
    ) -> Result<String, String>;
    fn is_feed_folder_path(&self, path: &std::path::Path) -> bool;
    fn is_storage_folder_path(&self, path: &std::path::Path) -> bool;
    fn is_system_folder_path(&self, path: &std::path::Path) -> bool;
    fn update_order_append(
        &self,
        dir: &std::path::Path,
        names: &[String],
        is_folder: bool,
    ) -> Result<(), String>;
    fn update_order_remove(
        &self,
        dir: &std::path::Path,
        names: &[String],
        is_folder: bool,
    ) -> Result<(), String>;
    fn update_order_rename(
        &self,
        dir: &std::path::Path,
        old_name: &str,
        new_name: &str,
        is_folder: bool,
    ) -> Result<(), String>;
    fn write_order_file(&self, dir: &std::path::Path, order: &OrderFile) -> Result<(), String>;
}

pub(crate) trait NoteBodyCrypto {
    fn decrypt_note_body(&self, body: &str) -> Result<String, String>;
}

pub(crate) trait NoteHistory {
    fn note_timestamps(&self, note_rel: &str) -> Result<(Option<i64>, Option<i64>), String>;
}

pub(crate) trait NoteIdGenerator {
    fn generate_note_id(&self) -> String;
    fn uuid_tail_without_timestamp_prefix(&self, note_id: &str) -> String;
}

pub(crate) trait NoteClock {
    fn now_ms(&self) -> Option<i64>;
    fn time_to_ms(&self, time: std::time::SystemTime) -> Option<i64>;
}

// ─── Implementation Notes ─────────────────────────────────────────────────────
//
// NoteService manages notes stored as markdown files with YAML-ish front-matter.
//
// get_tree()
//   in:  nothing
//   out: FolderNode — the full folder hierarchy from the notes root
//   - Hidden storage folders (Recordings/, Attachments/) are excluded from the tree
//   - Each folder contains its child folders and the notes inside it
//   - Folders are sorted by a persisted order file (.notes-order.json), alphabetical fallback
//   - The "Feed" folder sorts notes by newest-first created timestamp instead
//
// read_note(path)
//   in:  path — relative to notes root, e.g. "Feed/my-note.md"
//   out: String — the note body text (markdown)
//   - Parses front-matter but only returns the body
//   - If encryption is active, the body must be decrypted transparently
//   - The caller never sees ciphertext
//
// create_note(folder_path, content, timestamp_ms, file_name_format)
//   in:  folder_path — where to create it, defaults to "Feed"
//        content — initial body text, defaults to empty
//        timestamp_ms — creation time in unix ms, defaults to now
//        file_name_format — how to name the file (timestamp slug, uuid, or uuid-prefix slug)
//   out: CreateNoteResult — contains the relative path of the created file
//   - Generates a UUID v7 id and populates front-matter automatically
//   - Must encrypt body if encryption is active
//   - Cannot create notes inside storage folders (Recordings/, Attachments/)
//
// write_note(path, content)
//   in:  path — relative path to the note
//        content — new body text (replaces existing)
//   out: nothing
//   - Preserves existing front-matter, only replaces the body
//   - Updates the updated_ms timestamp
//   - Must encrypt if encryption is active
//
// set_note_timestamp(path, timestamp_ms)
//   in:  path — relative path to the note
//        timestamp_ms — new timestamp in unix ms
//   out: nothing
//   - Updates created_ms if the new value is earlier, always updates updated_ms
//   - Preserves the note body
//
// get_note_meta(path)
//   in:  path — relative path to the note
//   out: NoteMeta — timestamps, type, recording/handwriting paths, transcription/ocr status
//   - Falls back to git history timestamps if front-matter has no timestamps
//   - Falls back to filesystem timestamps if git has no history
//
// move_items(items, destination)
//   in:  items — list of relative paths (notes or folders)
//        destination — relative path to target folder
//   out: nothing
//   - Cannot move system folders (Feed, Archieve, Recordings, Attachments)
//   - Updates ordering files in both source and destination folders
//
// delete_items(items)
//   in:  items — list of relative paths (notes or folders)
//   out: nothing
//   - Deletes recursively for folders
//   - Cannot delete system folders
//   - Permanent — no trash/undo
//
// rename_item(path, new_name)
//   in:  path — relative path to the item
//        new_name — the new filename or folder name
//   out: String — the new relative path after rename
//   - Cannot rename system folders
//   - Updates ordering files
//
// set_order(parent, folder_order, note_order)
//   in:  parent — relative path to the folder
//        folder_order — ordered list of subfolder names
//        note_order — ordered list of note filenames
//   out: nothing
//   - Persists to .notes-order.json inside the folder
//   - Feed folder ignores custom order (always sorted by timestamp)
//
// Key assumptions for any implementation:
//   - Paths are always relative to a "notes root" directory
//   - Notes are markdown files with YAML-ish front-matter (--- delimited)
//   - Front-matter fields: id, created_ms, updated_ms, type, plus domain-specific fields
//   - Encryption is transparent: encrypt on write, decrypt on read
//   - The note ID is a UUID v7 string, generated once at creation
//   - Timestamps are Unix milliseconds
//   - System folders (Feed, Archieve, Recordings, Attachments) are protected from move/delete/rename

